"""Nível 1 — Tema 1 (Números naturais: aulas 11–14) e Tema 2 (Números inteiros: aulas 15–17)."""
from common import *
import math

def fac(n):
    out = []; m = n; p = 2
    while p * p <= m:
        e = 0
        while m % p == 0: m //= p; e += 1
        if e: out.append((p, e))
        p += 1
    if m > 1: out.append((m, 1))
    return out
def facs(n): return ' × '.join(f"{p}" if e == 1 else f"{p}^{e}" for p, e in fac(n))
def factex(n): return '\\times'.join(f"{p}" if e == 1 else f"{p}^{{{e}}}" for p, e in fac(n))

