ex.append(num(3, C, "Calcula o m.d.c.(48, 72, 120).", math.gcd(48, math.gcd(72, 120)), "48 = 2⁴·3, 72 = 2³·3², 120 = 2³·3·5. Comuns com menor expoente: 2³·3 = 24.", ["Decompõe os três.", "m.d.c. = 24."]))
